import{_ as d,C as a,o as s,c as n,aj as o,E as r}from"./framework.js";const u=JSON.parse('{"title":"税（税费） | Cms / Commerce | Documentation","description":"按 国家/地区 配置电商 税费：每个国家一条规则，含 基础税率，并可对省/州 区域覆盖、对特定 商品条件 覆盖。购物车试算与 订单 结账会按收货国家/地区及商品匹配税率（行级 taxAmount、订单合计税费）。","frontmatter":{"title":"税（税费） | Cms / Commerce | Documentation","description":"按 国家/地区 配置电商 税费：每个国家一条规则，含 基础税率，并可对省/州 区域覆盖、对特定 商品条件 覆盖。购物车试算与 订单 结账会按收货国家/地区及商品匹配税率（行级 taxAmount、订单合计税费）。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/commerce/taxes.html"}]]},"headers":[],"relativePath":"zh/cms/commerce/taxes.md","filePath":"cms/commerce/taxes.md","lastUpdated":1780453995000}'),c={name:"zh/cms/commerce/taxes.md"};function i(g,t,l,h,m,b){const e=a("DocImage");return s(),n("div",null,[t[0]||(t[0]=o('<h1 id="税-税费" tabindex="-1">税（税费） <a class="header-anchor" href="#税-税费" aria-label="Permalink to &quot;税（税费）&quot;">​</a></h1><blockquote><p>菜单：<strong>电商 → 税</strong><br> 深链：<code>/_Admin/commerce/taxes?SiteId={站点GUID}</code><br><strong>新建</strong>：<code>/_Admin/commerce/taxes/create?SiteId=...&amp;country={国家名}</code><br><strong>编辑</strong>：<code>/_Admin/commerce/taxes/edit?SiteId=...&amp;id={税规则Id}</code></p></blockquote><p>按 <strong>国家/地区</strong> 配置电商 <strong>税费</strong>：每个国家一条规则，含 <strong>基础税率</strong>，并可对省/州 <strong>区域覆盖</strong>、对特定 <strong>商品条件</strong> 覆盖。购物车试算与 <a href="./orders.html">订单</a> 结账会按收货国家/地区及商品匹配税率（行级 <code>taxAmount</code>、订单合计税费）。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><p>菜单权限特性名为 <code>tax</code>（非 <code>taxes</code>），编辑操作需 <code>tax</code> · <code>edit</code>。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>电商 → 税</strong>（及父级 <strong>电商</strong>）。</li><li>左侧 <strong>电商 → 税</strong>。</li></ol><h2 id="列表页" tabindex="-1">列表页 <a class="header-anchor" href="#列表页" aria-label="Permalink to &quot;列表页&quot;">​</a></h2><p>路径：<code>/_Admin/commerce/taxes?SiteId=...</code></p><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>国家</strong></td><td>国旗 + 本地化国名（Commerce 国家库）</td></tr><tr><td><strong>基础税</strong></td><td><code>baseTax</code>，百分比展示</td></tr><tr><td><strong>创建</strong></td><td>打开 <strong>选择国家</strong> 弹窗；已配置过的国家不会出现在列表中</td></tr><tr><td><strong>编辑</strong></td><td>行内铅笔 → <a href="#新建与编辑">新建与编辑</a></td></tr><tr><td><strong>批量删除</strong></td><td>勾选多行 → <strong>删除</strong> → 确认</td></tr></tbody></table>',9)),r(e,{src:"/cms/commerce/taxes-list.png",alt:"税规则列表：国家与基础税率",width:"1120"}),t[1]||(t[1]=o('<h3 id="选择国家弹窗" tabindex="-1">选择国家弹窗 <a class="header-anchor" href="#选择国家弹窗" aria-label="Permalink to &quot;选择国家弹窗&quot;">​</a></h3><p>点击 <strong>创建</strong> 后选择尚未配置税规则的国家；支持关键词筛选，点表格行即进入新建页（查询参数 <code>country</code>）。弹窗为 <code>SelectCountryDialog</code>：上方搜索框 + 国家表格（名称、代码）。</p><div class="tip custom-block"><p class="custom-block-title">创建按钮权限</p><p>列表 <strong>创建</strong> 按钮使用权限 <code>taxes</code> · <code>edit</code>，而菜单注册为 <code>tax</code> · <code>edit</code>。若按钮呈「无权限」禁用，仍可由具备税编辑权限的账号直接访问 <code>taxes/create?SiteId=...&amp;country={国家名}</code> 新建。</p></div><h2 id="新建与编辑" tabindex="-1">新建与编辑 <a class="header-anchor" href="#新建与编辑" aria-label="Permalink to &quot;新建与编辑&quot;">​</a></h2><p>新建路径带 <code>country</code>；编辑路径带 <code>id</code>。面包屑为 <strong>税 → {国家名}</strong>。表单共用 <code>EditForm</code>，底部 <strong>保存</strong> / <strong>取消</strong> 返回列表。</p>',5)),r(e,{src:"/cms/commerce/taxes-edit.png",alt:"税规则编辑：基础税、区域覆盖与商品覆盖",width:"1120"}),t[2]||(t[2]=o('<h3 id="基础税" tabindex="-1">基础税 <a class="header-anchor" href="#基础税" aria-label="Permalink to &quot;基础税&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>基础税</strong></td><td><code>baseTax</code>，百分比数字（<code>ElInputNumber</code>，步进 0.1，最小 0）</td></tr></tbody></table><h3 id="区域覆盖" tabindex="-1">区域覆盖 <a class="header-anchor" href="#区域覆盖" aria-label="Permalink to &quot;区域覆盖&quot;">​</a></h3><p>当该国家在 Commerce 地址库中存在 <strong>省/州等地区</strong> 时显示 <strong>区域覆盖</strong> 卡片：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>搜索</strong></td><td>按关键词筛选地区列表</td></tr><tr><td><strong>重置</strong></td><td>清空关键词并移除全部区域覆盖项</td></tr><tr><td><strong>分页</strong></td><td>每页 6 个地区</td></tr><tr><td><strong>每地区税率</strong></td><td>百分比 + <strong>计算方式</strong> 下拉</td></tr></tbody></table><p>计算方式（<code>OverridesType</code>）三种（文案中含当前基础税 <code>{tax}%</code>）：</p><table tabindex="0"><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td><strong>Added</strong></td><td>在基础税 <strong>之上加收</strong> 该百分比</td></tr><tr><td><strong>Instead</strong></td><td><strong>替代</strong> 基础税，仅使用该百分比</td></tr><tr><td><strong>Compounded</strong></td><td>在基础税之上 <strong>复合</strong> 计算（叠乘逻辑由服务端实现）</td></tr></tbody></table><p>未单独配置的地区使用 <strong>基础税</strong>。</p><h3 id="商品覆盖" tabindex="-1">商品覆盖 <a class="header-anchor" href="#商品覆盖" aria-label="Permalink to &quot;商品覆盖&quot;">​</a></h3><p><strong>商品覆盖</strong> 可添加多条规则，每条包含：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>税率</strong></td><td>百分比</td></tr><tr><td><strong>计算方式</strong></td><td>相对「基础税 + 已匹配区域覆盖」的 Added / Instead / Compounded（文案与区域覆盖类似，表述为含区域结果）</td></tr><tr><td><strong>条件</strong></td><td><code>Condition</code> 组件：匹配 <strong>商品</strong> 维度字段（schema 来自 <code>getTaxSchemas</code>），支持且/或多条</td></tr><tr><td><strong>完成</strong></td><td>编辑中点 <strong>完成</strong> 收起为摘要；点击摘要可再次展开</td></tr><tr><td><strong>删除</strong></td><td>移除该条商品覆盖</td></tr><tr><td><strong>添加</strong></td><td>圆形 <strong>+</strong> 按钮新增一条</td></tr></tbody></table><p>满足条件的商品行在试算/下单时套用对应覆盖税率，否则回退到区域/基础税。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./orders.html">订单</a> — 行税费与合计税</li><li><a href="./carts.html">购物车</a> — 结账模式试算含税</li><li><a href="./currencies.html">货币</a>、<a href="./settings.html">设置</a></li><li><a href="/kb-docs/zh/api/commerce/commerce.html">k.commerce</a>（购物车/订单试算中的 <code>taxAmount</code>）</li></ul>',14))])}const _=d(c,[["render",i]]);export{u as __pageData,_ as default};
